import { useState } from "react";
import styles from "./exportReports.module.css";
import GeneralBtn from "../../../General/GeneralBtn/GeneralBtn";
import DateTimePicker from "../../../General/DateTimePicker/DateTimePicker";
import GeneralSelection from "../../../General/GeneralSelection/GeneralSelection";
import ReportPreviewPopup from "../ReportPreviewPopup/ReportPreviewPopup.jsx";

//all the kinds of reports which can be generated by the manager
const reportOptions = [
  { value: "", label: "Select report type" },
  { value: "users", label: "Users Report" },
  { value: "inventory", label: "Inventory Report" },
  { value: "orders", label: "Orders Report" },
  { value: "performance", label: "Sales Performance Report" },
];

function ExportReports() {
  const [reportType, setReportType] = useState(""); //report type to chose
  const [from, setFrom] = useState(""); //from date
  const [to, setTo] = useState(""); //to date
  const [error, setError] = useState(""); //error dates
  const [previewUrl, setPreviewUrl] = useState("");
  const [showPreview, setShowPreview] = useState(false);

  const today = new Date();

  //the report types which require dates range
  const requiresDates = reportType === "inventory" || reportType === "orders";

  //preparing the selected report for perview
  function handlePreview() {
    console.log("Preview button clicked");
    if (!reportType) return;

    //checking the selected date range
    if (requiresDates && (!from || !to || from > to)) {
      setError("Please select a valid date range");
      return;
    }
    setError("");
    const url = requiresDates
      ? `/api/manager/reports/${reportType}?from=${from}&to=${to}`
      : `/api/manager/reports/${reportType}`;
    console.log("Report URL:", url);
    setPreviewUrl(url);
    setShowPreview(true);
  }

  //setting from value
  function handleFromChange(value) {
    setFrom(value);
    if (to && value && value > to) setTo("");
    setError("");
  }

  //setting to value
  function handleToChange(value) {
    setTo(value);
    setError("");
  }
  return (
    <section className={styles.exportReports}>
      <div className={styles.header}>
        <h2>Export Reports</h2>
        <p>Generate, preview and download reports in PDF format.</p>
      </div>

      <div className={styles.form}>
        <div className={styles.field}>
          <label className={styles.label}>REPORT TYPE</label>

          <GeneralSelection
            value={reportType}
            options={reportOptions}
            onChange={(e) => {
              setReportType(e.target.value);
              setFrom("");
              setTo("");
              setError("");
            }}
          />
        </div>

        {requiresDates ? (
          <div className={styles.dateFields}>
            <DateTimePicker
              label="FROM"
              value={from}
              onChange={handleFromChange}
              maxDate={to || today}
              dateOnly
            />

            <DateTimePicker
              label="TO"
              value={to}
              onChange={handleToChange}
              minDate={from}
              maxDate={today}
              dateOnly
            />
          </div>
        ) : (
          <div className={styles.emptyDates}></div>
        )}

        <GeneralBtn
          text="PREVIEW REPORT"
          type="button"
          onClick={handlePreview}
          disabled={
            !reportType || (requiresDates && (!from || !to || from > to))
          }
          className={styles.exportBtn}
        />
      </div>

      {error && <p className={styles.error}>{error}</p>}
      {showPreview && (
        <ReportPreviewPopup
          url={previewUrl}
          onClose={() => {
            setShowPreview(false);
            setPreviewUrl("");
          }}
        />
      )}
    </section>
  );
}

export default ExportReports;
